### API Client with Exception Handling
```python
import requests
from typing import Dict, Any

class APIError(Exception):
    """Custom exception for API errors"""
    def __init__(self, message, status_code=None, response_data=None):
        self.message = message
        self.status_code = status_code
        self.response_data = response_data
        super().__init__(self.message)

class APIClient:
    def __init__(self, base_url: str, timeout: int = 30):
        self.base_url = base_url
        self.timeout = timeout

    def make_request(self, endpoint: str, method: str = 'GET', **kwargs) -> Dict[str, Any]:
        """
        Make an API request with comprehensive error handling.
        """
        url = f"{self.base_url}/{endpoint.lstrip('/')}"

        try:
            response = requests.request(
                method=method,
                url=url,
                timeout=self.timeout,
                **kwargs
            )

            # Check for HTTP errors
            response.raise_for_status()

            # Parse JSON response
            try:
                return response.json()
            except ValueError:
                # Response is not JSON
                return {'data': response.text, 'status_code': response.status_code}

        except requests.exceptions.Timeout:
            raise APIError(f"Request timeout after {self.timeout} seconds")

        except requests.exceptions.ConnectionError:
            raise APIError("Failed to connect to the API server")

        except requests.exceptions.HTTPError as e:
            status_code = e.response.status_code
            try:
                error_data = e.response.json()
            except ValueError:
                error_data = {'error': e.response.text}

            if status_code == 401:
                raise APIError("Authentication failed", status_code, error_data)
            elif status_code == 403:
                raise APIError("Access forbidden", status_code, error_data)
            elif status_code == 404:
                raise APIError("Resource not found", status_code, error_data)
            elif status_code >= 500:
                raise APIError("Server error", status_code, error_data)
            else:
                raise APIError(f"HTTP {status_code} error", status_code, error_data)

        except Exception as e:
            raise APIError(f"Unexpected error: {str(e)}") from e

# Usage example
def get_user_data(user_id: int):
    client = APIClient("https://api.example.com")

    try:
        data = client.make_request(f"/users/{user_id}")
        return data
    except APIError as e:
        if e.status_code == 404:
            return None  # User not found
        elif e.status_code == 401:
            # Re-authenticate and retry
            authenticate()
            return client.make_request(f"/users/{user_id}")
        else:
            logger.error(f"API error: {e.message}")
            raise
```
